// Actual runtime archive/load/recovery verification. Explicit isolated native probe only; no OS input.
using System;using System.Collections;using System.Collections.Generic;using System.IO;using System.Linq;
using Newtonsoft.Json;using Newtonsoft.Json.Linq;using Sdt.Core;using Sdt.Run;using Sdt.UI.Kit;using Sdt.UI.Screens.Run;using Sdt.UI.Screens.Menu;
using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.EventSystems;using UnityEngine.UI;
namespace Sdt.Editor
{
 [InitializeOnLoad]public static class CurrentSlotArchiveValidation
 {
  const string Active="Sdt.SlotArchive.Active";static IEnumerator _flow;static double _start;static string _step;static readonly List<object> Records=new List<object>();
  static string Output=>Environment.GetEnvironmentVariable("SDT_UNITY_CHECK_OUTPUT");
  static CurrentSlotArchiveValidation(){EditorApplication.update+=Tick;Application.logMessageReceived+=Observe;}
  public static void Run(){if(string.IsNullOrWhiteSpace(Output))throw new InvalidOperationException("Output required");Directory.CreateDirectory(Output);Environment.SetEnvironmentVariable("SDT_UNITY_TEST_DATA",Path.Combine(Output,"profile-archive"));AssetDatabase.DisallowAutoRefresh();SessionState.SetBool(Active,true);EditorSceneManager.OpenScene("Assets/Scenes/Bootstrap.unity");EditorApplication.EnterPlaymode();}
  static void Observe(string text,string stack,LogType type){if(SessionState.GetBool(Active,false)&&(type==LogType.Error||type==LogType.Exception))Finish(new InvalidOperationException(text+"\n"+stack));}
  static void Tick(){if(!SessionState.GetBool(Active,false))return;EditorApplication.QueuePlayerLoopUpdate();if(!EditorApplication.isPlaying||EditorApplication.isCompiling||App.Canvas==null)return;if(_start==0)_start=EditorApplication.timeSinceStartup;try{Require(EditorApplication.timeSinceStartup-_start<100,"archive timeout "+_step);if(_flow==null)_flow=Flow();if(!_flow.MoveNext())Finish(null);}catch(Exception e){Finish(e);}}
  static IEnumerator Flow()
  {
   var g=GameRuntime.I;_step="five actual new runs and isolated partitions";
   for(int slot=1;slot<=5;slot++){Clear();g.ResetSlot(slot);g.NewRun(slot,CharacterTable.All[0].id);for(int i=0;i<g.GetEntrySupplyCards().Count;i++)Require(g.ClaimEntrySupply(i,out var e),e);g.State.coins=slot*3;g.Base.coins=slot*11;g.SaveCurrent();Require(g.Saves.LastWriteSucceeded,"new run save failed");}
   Clear();g.Saves.Global.SetString("archive-native-global","preserve");string original=File.ReadAllText(SaveSystem.ProfilePath),archive=g.Saves.ExportSlotArchive(1);var preview=g.Saves.PreviewSlotArchive(archive,2);Require(!g.Saves.ImportSlotArchive(preview,false,out _),"unconfirmed import accepted");
   using(var locked=new FileStream(SaveSystem.ProfilePath,FileMode.Open,FileAccess.Read,FileShare.Read))Require(!g.Saves.ImportSlotArchive(preview,true,out _)&&File.ReadAllText(SaveSystem.ProfilePath)==original&&!g.Saves.InTransaction,"failed write lost original");
   Require(g.Saves.ImportSlotArchive(preview,true,out var reason),reason);Require(g.LoadRun(2)&&g.ActiveSlot==2&&g.State.slot==2&&g.State.coins==3&&g.Base.coins==11,"imported live run failed actual LoadRun");
   var before=JObject.Parse(original);var after=JObject.Parse(File.ReadAllText(SaveSystem.ProfilePath));foreach(int slot in new[]{1,3,4,5})Require(JToken.DeepEquals(before["runs"][slot.ToString()],after["runs"][slot.ToString()])&&JToken.DeepEquals(before["global"][BaseData.SlotKeyPrefix+slot],after["global"][BaseData.SlotKeyPrefix+slot]),"unrelated slot changed "+slot);Require(g.Saves.Global.GetString("archive-native-global")=="preserve","global changed");Record();yield return null;
   _step="battle entry nested identity rebound and actual resume";Clear();g.State.Phase="idle";g.Bus.Emit(new BattleRequested{Request=new BattleRequest{Name="档案原生恢复验收",Foes=new List<EnemyStats>{new EnemyStats{id="native-frame-foe",name="受控敌人",hp=1000,atk=0}}}});
   double deadline=EditorApplication.timeSinceStartup+8;while(g.BattleCheckpoint==null&&EditorApplication.timeSinceStartup<deadline)yield return null;Require(g.BattleCheckpoint!=null,"actual battle checkpoint absent");g.SaveCurrent();string battle=g.Saves.ExportSlotArchive(2);var bp=g.Saves.PreviewSlotArchive(battle,4);Require(g.Saves.ImportSlotArchive(bp,true,out reason),reason);Clear();Require(g.LoadRun(4)&&g.ActiveSlot==4&&g.BattleCheckpoint?.run.slot==4&&g.State.battleActive,"battle archive did not resume with rebound entry");Record();yield return null;
   _step="pending extraction real creation cross-slot resume";Clear();Require(g.LoadRun(3),"load extraction source failed");Clear();g.State.ownedCards.Add(new OwnedCard{uid="archive-extraction-probe",card=CardLibrary.FindByName("冰刺").Clone()});Require(g.DoExtract()!=null,"actual DoExtract failed");var pending=g.Saves.PreviewSlotArchive(g.Saves.ExportSlotArchive(3),5);Require(pending.PendingExtraction,"pending extraction not detected");Require(g.Saves.ImportSlotArchive(pending,true,out reason),reason);Clear();Require(g.LoadRun(5)&&g.ActiveSlot==5&&g.CurrentExtraction!=null&&g.Saves.GetSettlement(5).identity=="5:"+g.State.seed&&g.Saves.GetSettlement(5).status=="sorting","pending extraction did not actually resume");Require(g.CurrentExtraction.Left.Any(s=>s.card.name=="冰刺"),"pending extraction contents lost");Record();yield return null;
   _step="stale cached instance cannot overwrite unrelated disk writes";var cached=new SaveSystem();cached.ReadSlot(1);var other=new SaveSystem();other.Global.SetString("archive-external","survive");string external=File.ReadAllText(SaveSystem.ProfilePath);bool blocked=false;try{cached.PreviewSlotArchive(archive,4);}catch{blocked=true;}Require(blocked&&File.ReadAllText(SaveSystem.ProfilePath)==external,"cached instance lost external global write");Record();
   _step="whole profile error refuses partial repair";var bad=new SaveSystem();string valid=File.ReadAllText(SaveSystem.ProfilePath);File.WriteAllText(SaveSystem.ProfilePath,"corrupt isolated archive probe");try{blocked=false;try{bad.PreviewSlotArchive(archive,1);}catch{blocked=true;}Require(blocked&&File.ReadAllText(SaveSystem.ProfilePath)=="corrupt isolated archive probe","partial repair overwrote unknown original");}finally{File.WriteAllText(SaveSystem.ProfilePath,valid);}Record();
  }
  static void Clear(){CurrentRunFilm.CancelActive();while(UiStack.Count>0)UiStack.Pop();}
  static void Record(){Records.Add(new{step=_step,activeSlot=GameRuntime.I.ActiveSlot,run=GameRuntime.I.State.runActive,profile=SaveSystem.ProfilePath});}
  static void Require(bool ok,string message){if(!ok)throw new InvalidOperationException(message);}
  static void Finish(Exception error){if(!SessionState.GetBool(Active,false))return;SessionState.SetBool(Active,false);File.WriteAllText(Path.Combine(Output,"result.json"),JsonConvert.SerializeObject(new{passed=error==null,error=error?.ToString(),step=_step,records=Records,osHardwareInput=false,scope="Actual runtime NewRun/LoadRun/battle checkpoint/extraction recovery, real file-lock failure and two SaveSystem instances; constructed positions/enemy. UI archive controls covered separately by actual standalone review."},Formatting.Indented));EditorApplication.Exit(error==null?0:2);}
 }
}
